from concurrent.futures import ThreadPoolExecutor
import threading
import time

import pytest


class Bad(Exception):
    def __init__(self, n: int) -> None:
        self.n = n


def check(x: int) -> int:
    if x % 2 == 1:
        raise Bad(x)
    return x


def all_even(xs: list[int]) -> list[int]:
    """Check every element of xs in parallel using a thread pool.

    Returns the checked values in input order. If any element is bad,
    raises the Bad of the lowest-index bad element, regardless of which
    check finishes first.
    """
    if not xs:
        return []
    with ThreadPoolExecutor(max_workers=len(xs)) as pool:
        futures = [pool.submit(check, x) for x in xs]
        results: list[int] = []
        first_bad: Bad | None = None
        for f in futures:
            try:
                results.append(f.result())
            except Bad as e:
                if first_bad is None:
                    first_bad = e
        if first_bad is not None:
            raise first_bad
        return results


def test_all_even_ok() -> None:
    assert all_even([2, 4, 6]) == [2, 4, 6]


def test_all_even_empty() -> None:
    assert all_even([]) == []


def test_all_even_preserves_order() -> None:
    xs = list(range(0, 200, 2))
    assert all_even(xs) == xs


def test_all_even_single_bad() -> None:
    with pytest.raises(Bad) as ei:
        all_even([2, 4, 5, 8])
    assert ei.value.n == 5


def test_all_even_lowest_index_bad_wins() -> None:
    with pytest.raises(Bad) as ei:
        all_even([2, 7, 4, 3, 9])
    assert ei.value.n == 7


def test_all_even_first_element_bad() -> None:
    with pytest.raises(Bad) as ei:
        all_even([1, 3, 5])
    assert ei.value.n == 1


def test_all_even_lowest_index_not_lowest_value() -> None:
    with pytest.raises(Bad) as ei:
        all_even([9, 1])
    assert ei.value.n == 9


def test_all_even_lowest_index_even_if_finishes_last(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    # The earlier bad element is slow; the later one fails immediately.
    # The result must still be the lowest-index Bad.
    started = threading.Event()

    def slow_check(x: int) -> int:
        if x == 1:
            started.wait(timeout=1.0)
            time.sleep(0.05)
        else:
            started.set()
        if x % 2 == 1:
            raise Bad(x)
        return x

    monkeypatch.setitem(globals(), "check", slow_check)
    with pytest.raises(Bad) as ei:
        all_even([1, 2, 3])
    assert ei.value.n == 1


def test_all_even_runs_in_parallel(monkeypatch: pytest.MonkeyPatch) -> None:
    # Two checks must be in flight simultaneously, or the barrier times out.
    barrier = threading.Barrier(2, timeout=2.0)

    def waiting_check(x: int) -> int:
        barrier.wait()
        return x

    monkeypatch.setitem(globals(), "check", waiting_check)
    assert all_even([2, 4]) == [2, 4]


def test_all_even_checks_every_element(monkeypatch: pytest.MonkeyPatch) -> None:
    seen: list[int] = []
    lock = threading.Lock()

    def recording_check(x: int) -> int:
        with lock:
            seen.append(x)
        if x % 2 == 1:
            raise Bad(x)
        return x

    monkeypatch.setitem(globals(), "check", recording_check)
    with pytest.raises(Bad):
        all_even([1, 2, 4, 6])
    assert sorted(seen) == [1, 2, 4, 6]

